#[derive(Debug, Clone)]
struct Line {
    flags: TokenFlags,
    tokens_start: u32,
    tokens_end: u32,
}

/// Keeps track of whether we are currently visiting a class or function definition in a
/// [`LogicalLine`]. If we are visiting a class or function, the state also keeps track
/// of the [type parameters] of the class/function.
///
/// Call [`DefinitionState::visit_token_kind`] on the [`TokenKind`] of each
/// successive [`LogicalLineToken`] to ensure the state remains up to date.
///
/// [type parameters]: https://docs.python.org/3/reference/compound_stmts.html#type-params
#[derive(Debug, Clone)]
struct DefinitionState {
    kind: DefinitionKind,
    fstrings: u32,
    grouping_parens: u32,
    operator_parens: u32,
    annotated_func_arg: bool,
    brackets: Vec<TokenKind>,
}

#[derive(Debug, Clone, Copy)]
enum DefinitionKind {
    InClass(TypeParamsState),
    InFunction(TypeParamsState),
    InTypeAlias(TypeParamsState),
    NotInDefinition,
}

impl DefinitionState {
    fn from_tokens<'a>(tokens: impl IntoIterator<Item = &'a LogicalLineToken>) -> Self {
        let mut token_kinds = tokens.into_iter().map(LogicalLineToken::kind);
        let kind = loop {
            match token_kinds.next() {
                Some(TokenKind::Indent | TokenKind::Dedent) => continue,
                Some(TokenKind::Class) => break DefinitionKind::InClass(TypeParamsState::default()),
                Some(TokenKind::Def) => {
                    break DefinitionKind::InFunction(TypeParamsState::default())
                }
                Some(TokenKind::Async) if matches!(token_kinds.next(), Some(TokenKind::Def)) => {
                    break DefinitionKind::InFunction(TypeParamsState::default())
                }
                Some(TokenKind::Type) => {
                    break DefinitionKind::InTypeAlias(TypeParamsState::default())
                }
                Some(_) | None => break DefinitionKind::NotInDefinition,
            }
        };
        Self {
            kind,
            fstrings: 0,
            grouping_parens: 0,
            operator_parens: 0,
            annotated_func_arg: false,
            brackets: Vec::new(),
        }
    }

    fn in_function_definition(&self) -> bool {
        matches!(self.kind, DefinitionKind::InFunction(_))
    }

    fn type_params_state(&self) -> Option<TypeParamsState> {
        match self.kind {
            DefinitionKind::InClass(state)
            | DefinitionKind::InFunction(state)
            | DefinitionKind::InTypeAlias(state) => Some(state),
            DefinitionKind::NotInDefinition => None,
        }
    }

    fn in_type_params(&self) -> bool {
        matches!(
            self.type_params_state(),
            Some(TypeParamsState::InTypeParams { .. })
        )
    }

    fn fstrings(&self) -> u32 {
        self.fstrings
    }

    fn grouping_parens(&self) -> u32 {
        self.grouping_parens
    }

    fn operator_parens(&self) -> u32 {
        self.operator_parens
    }

    fn annotated_func_arg(&self) -> bool {
        self.annotated_func_arg
    }

    fn last_bracket_is_square(&self) -> bool {
        matches!(self.brackets.last(), Some(TokenKind::Lsqb))
    }

    fn bracket_count(&self) -> usize {
        self.brackets.len()
    }

    fn visit_token_kind(&mut self, token_kind: TokenKind) {
        let in_class = matches!(self.kind, DefinitionKind::InClass(_));
        let in_function = matches!(self.kind, DefinitionKind::InFunction(_));
        let in_type_alias = matches!(self.kind, DefinitionKind::InTypeAlias(_));
        let in_definition = in_class || in_function || in_type_alias;

        if !is_non_logical_token(token_kind) {
            if matches!(token_kind, TokenKind::FStringStart) {
                let next_depth = self.fstrings.saturating_add(1);
                self.fstrings = next_depth;
            } else if matches!(token_kind, TokenKind::FStringEnd) {
                let next_depth = self.fstrings.saturating_sub(1);
                self.fstrings = next_depth;
            } else {
                match token_kind {
                    TokenKind::Lpar => {
                        let next_grouping = self.grouping_parens.saturating_add(1);
                        let next_operator = self.operator_parens.saturating_add(1);
                        self.grouping_parens = next_grouping;
                        self.operator_parens = next_operator;
                    }
